// Bainpaint — sound effects (tiny.audio.sampler only).
//
// Never routes Web Audio to ctx.destination (Linux crackles). Short synthesized
// clips live in resources/sfx/*.wav (generated by tools/makesfx.js) and are
// loaded into the app-scoped sampler. A View ▸ Sound Effects toggle mutes.
(() => {
  const BP = (window.BP = window.BP || {});
  const KEY = 'bp.sfx';
  const NAMES = ['click', 'save', 'open', 'error', 'success'];

  const sfx = {
    enabled: true,
    _ready: false,

    async init() {
      try { this.enabled = (await tiny.store.get(KEY)) !== false; } catch { this.enabled = true; }
      try {
        const paths = await tiny.app.paths();
        if (!paths.resources) return;
        for (const name of NAMES) {
          try { await tiny.audio.sampler.load(name, `${paths.resources}/sfx/${name}.wav`); } catch { /* missing clip */ }
        }
        this._ready = true;
      } catch { /* sampler unavailable */ }
      BP.emit('sfx:changed', this.enabled);
    },

    play(name) {
      if (!this.enabled || !this._ready) return;
      try { tiny.audio.sampler.play(name, { vol: 0.5 }); } catch { /* ignore */ }
    },

    setEnabled(on) {
      this.enabled = !!on;
      try { tiny.store.set(KEY, this.enabled); } catch { /* ignore */ }
      if (!this.enabled) { try { tiny.audio.sampler.stopAll(); } catch { /* ignore */ } }
      BP.emit('sfx:changed', this.enabled);
    },
    toggle() { this.setEnabled(!this.enabled); },
  };

  BP.sfx = sfx;
})();
